"""Dataset registry. Every dataset is a directory of tasks under the data root."""

from __future__ import annotations

from dataclasses import replace
from pathlib import Path

from semjoin.core import JoinTask
from semjoin.datasets.pairdir import read_dataset

# autofj:  downloaded by `semjoin download-autofj`
# mapping: generated by `semjoin build-mapping` (ISO tables and mixed-type tasks)
# wikidata: queried by `semjoin download-wikidata`; the built tasks are committed
# autojoin: real web tables, downloaded by `semjoin download-autojoin`; held out (test only)
# nyc:     real NYC Open Data joins, queried by `semjoin download-nyc`; committed; held out
# freyja:  labeled by hand, see docs/data-format.md
DATASETS = ("autofj", "mapping", "wikidata", "autojoin", "nyc", "freyja")


def load_tasks(
    names: list[str],
    data_root: Path,
    manifest: dict[str, str] | None = None,
    split: str | None = None,
) -> list[JoinTask]:
    """Load tasks, attach splits from the manifest, optionally filter by split."""
    tasks = []
    for name in names:
        if name not in DATASETS:
            raise ValueError(f"unknown dataset {name!r}; choose from {DATASETS}")
        tasks.extend(read_dataset(data_root / name, name))
    if manifest is not None:
        missing = [t.key for t in tasks if t.key not in manifest]
        if missing:
            raise ValueError(
                f"{len(missing)} tasks missing from split manifest (e.g. {missing[0]}); "
                "run `semjoin split` first"
            )
        tasks = [replace(t, split=manifest[t.key]) for t in tasks]
    if split is not None:
        tasks = [t for t in tasks if t.split == split]
    return tasks
